"""Ready-made white-model scenes (scene code written to the scene prompt); 'try' and the built-in AI render one without a model writing code."""

PRESETS = (
    dict(id='cat', name='橘猫跳上书架', shot='一只橘猫在客厅地板上蹲下蓄力，沿着错落的书架层板一级一级跳上去，最后蹲在最高一层，镜头侧面平移并略微上摇跟随。',
         prompt='A ginger cat crouches on a living room floor, gathers itself and leaps up a staggered wooden bookshelf, jumping from one shelf to the next between rows of books, and finally settles on the top shelf, while the camera pans sideways and tilts up slightly to follow. Warm indoor daylight, realistic fur and wood, soft shadows, smooth camera motion. Soft room tone and the light thud of paws on wood.',
         seconds=5,
         code='export function build(THREE) {\n  const scene = new THREE.Scene();\n  const camera = new THREE.PerspectiveCamera(65, 960 / 544, 0.1, 300);\n  const std = c => new THREE.MeshStandardMaterial({ color: c, roughness: 1 });\n  const add = (geo, mat, x, y, z, name, parent) => {\n    const m = new THREE.Mesh(geo, mat); m.position.set(x, y, z); m.name = name || "";\n    m.castShadow = true; m.receiveShadow = true; (parent || scene).add(m); return m;\n  };\n  const ss = x => x * x * (3 - 2 * x);\n  const lerp = (a, b, u) => a + (b - a) * u;\n  const clamp01 = x => Math.min(1, Math.max(0, x));\n  const sun = new THREE.DirectionalLight(0xffffff, 1.8);\n  sun.castShadow = true; sun.shadow.mapSize.set(2048, 2048);\n  sun.shadow.camera.left = -60; sun.shadow.camera.right = 60; sun.shadow.camera.top = 60; sun.shadow.camera.bottom = -60; sun.shadow.camera.far = 200;\n  scene.add(sun);\n\n  scene.background = new THREE.Color(0xe9e2d6);\n  scene.add(new THREE.HemisphereLight(0xfff4e6, 0x8a7f72, 1.2)); sun.position.set(6, 10, 8);\n  add(new THREE.PlaneGeometry(14, 10).rotateX(-Math.PI / 2), std(0xb88f65), 0, 0, 0, "floor");\n  add(new THREE.BoxGeometry(14, 4, 0.2), std(0xe9e2d6), 0, 2, -1.2, "wall");\n  // bookshelf: two side boards, staggered shelves\n  add(new THREE.BoxGeometry(0.1, 2.6, 0.5), std(0x7a5232), -1.4, 1.3, -0.9, "side");\n  add(new THREE.BoxGeometry(0.1, 2.6, 0.5), std(0x7a5232), 1.4, 1.3, -0.9, "side");\n  const shelves = [[0.6, -0.9], [1.2, -0.4], [1.8, 0.2], [2.4, 0.6]];\n  const stepsX = [-0.9, -0.2, 0.5, 1.0], ys = [0.55, 1.05, 1.55, 2.1];\n  for (let i = 0; i < 4; i++) {\n    add(new THREE.BoxGeometry(1.0, 0.06, 0.5), std(0x9a6b3f), stepsX[i], ys[i] - 0.03, -0.9, "shelf");\n    for (let k = 0; k < 3; k++) add(new THREE.BoxGeometry(0.12, 0.28, 0.3), std([0x3c6ea8, 0xb04a4a, 0x4a8a5a][(i + k) % 3]), stepsX[i] - 0.3 + k * 0.2, ys[i] + 0.14, -1.0, "book");\n  }\n  add(new THREE.BoxGeometry(0.9, 0.5, 0.5), std(0x6b7b8c), -2.6, 0.25, 0.6, "sofa_block");\n  const cat = new THREE.Group(); cat.name = "hero_cat"; scene.add(cat);\n  const orange = std(0xe58a2e);\n  const body = add(new THREE.BoxGeometry(0.42, 0.22, 0.2), orange, 0, 0.18, 0, "hero_cat_body", cat);\n  add(new THREE.SphereGeometry(0.11, 10, 8), orange, 0.26, 0.28, 0, "hero_cat_head", cat);\n  add(new THREE.ConeGeometry(0.035, 0.08, 4), orange, 0.28, 0.4, 0.06, "hero_cat_ear", cat);\n  add(new THREE.ConeGeometry(0.035, 0.08, 4), orange, 0.28, 0.4, -0.06, "hero_cat_ear", cat);\n  const tail = add(new THREE.CylinderGeometry(0.03, 0.03, 0.4, 6), orange, -0.34, 0.3, 0, "hero_cat_tail", cat);\n  tail.rotation.z = 0.8;\n  // waypoints: floor crouch, jump to each shelf\n  const wp = [[-1.9, 0.0, 0.1], [-1.9, 0.0, 0.1], [stepsX[0], ys[0], -0.9], [stepsX[1], ys[1], -0.9], [stepsX[2], ys[2], -0.9], [stepsX[3], ys[3], -0.9], [stepsX[3], ys[3], -0.9]];\n  const times = [0, 0.7, 1.4, 2.3, 3.2, 4.1, 5.0];\n  const pos = t => { let i = 0; while (i < 5 && t > times[i + 1]) i++;\n    const u = clamp01((t - times[i]) / (times[i + 1] - times[i])); const a = wp[i], b = wp[i + 1];\n    const arc = (i >= 1 && i <= 4) ? Math.sin(Math.PI * u) * 0.45 : 0;\n    const e = ss(u); return new THREE.Vector3(lerp(a[0], b[0], e), lerp(a[1], b[1], u) + arc, lerp(a[2], b[2], e)); };\n  return { scene, camera, update(t) {\n    const p = pos(t); cat.position.copy(p);\n    cat.scale.y = (t < 0.7) ? 1 - 0.35 * Math.sin(Math.PI * clamp01(t / 0.7)) : 1;\n    cat.rotation.z = (t > 0.7 && t < 4.1) ? 0.35 : 0;\n    camera.position.set(p.x * 0.6, 0.9 + p.y * 0.5, 2.7);\n    camera.lookAt(p.x * 0.85, 0.35 + p.y * 0.85, -0.9);\n  } };\n}\n'),
)


def preset(identity):
    return next((row for row in PRESETS if row['id'] == identity), None)
